import React, { useEffect, useState } from 'react';
import { MdKeyboardArrowDown, MdOutlineLiveTv } from "react-icons/md";
import { useNavigate, useParams } from 'react-router-dom';
import ConfirmationModal from "../components/common/ConfirmationModal";
import Footer from '../components/common/Footer';
import RatingStars from '../components/common/RatingStars';
import CourseBuyCard from '../components/core/CoursePage/CourseBuyCard';
import { fetchCourseDetails } from '../services/operations/courseDetailsAPI';
import GetAvgRating from '../utils/avgRating';

function App() {
  const [course, setCourse] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [openSections, setOpenSections] = useState([]);

  useEffect(() => {
    // Simulated course data fetch
    const fetchCourse = async () => {
      try {
        setLoading(true);
        // Replace this with your actual API call
        const response = await new Promise((resolve) => {
          setTimeout(() => {
            resolve({
              id: '1',
              courseName: 'Advanced Web Development',
              courseDescription: 'Master modern web development with this comprehensive course',
              price: 99.99,
              instructor: {
                firstName: 'John',
                lastName: 'Doe',
                image: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=400&h=400&fit=crop'
              },
              whatYouWillLearn: 'Build professional web applications with React, Node.js, and modern tools',
              courseContent: [
                {
                  sectionName: 'Getting Started',
                  subSection: [
                    {
                      title: 'Course Introduction',
                      description: 'Overview of what you will learn'
                    }
                  ]
                }
              ],
              ratingAndReview: [{ rating: 5 }, { rating: 4 }],
              studentsEnrolled: ['1', '2', '3']
            });
          }, 1000);
        });
        setCourse(response);
      } catch (err) {
        setError('Failed to load course details');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchCourse();
  }, []);

  const toggleSection = (index) => {
    setOpenSections(prev => 
      prev.includes(index) 
        ? prev.filter(i => i !== index)
        : [...prev, index]
    );
  };

  const getAverageRating = () => {
    if (!course?.ratingAndReview?.length) return 0;
    const sum = course.ratingAndReview.reduce((acc, curr) => acc + curr.rating, 0);
    return (sum / course.ratingAndReview.length).toFixed(1);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  if (error || !course) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <h2 className="text-xl font-semibold text-gray-800">Error Loading Course</h2>
          <p className="mt-2 text-gray-600">{error || 'Course not found'}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Hero Section */}
      <div className="bg-gray-900 text-white">
        <div className="max-w-7xl mx-auto px-4 py-16 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div>
              <h1 className="text-4xl font-bold">{course.courseName}</h1>
              <p className="mt-4 text-gray-300">{course.courseDescription}</p>
              <div className="mt-6 flex items-center space-x-4">
                <span className="text-yellow-400 text-xl font-semibold">
                  {getAverageRating()}
                </span>
                <span className="text-gray-400">
                  ({course.ratingAndReview.length} reviews)
                </span>
                <span className="text-gray-400">
                  {course.studentsEnrolled.length} students
                </span>
              </div>
              <div className="mt-4 flex items-center space-x-2">
                <img
                  src={course.instructor.image}
                  alt={`${course.instructor.firstName} ${course.instructor.lastName}`}
                  className="w-10 h-10 rounded-full"
                />
                <span className="text-gray-300">
                  Created by {course.instructor.firstName} {course.instructor.lastName}
                </span>
              </div>
            </div>
            <div className="lg:pl-8">
              <div className="bg-white rounded-lg p-6 shadow-lg">
                <div className="text-gray-900">
                  <div className="text-3xl font-bold">${course.price}</div>
                  <button className="mt-4 w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 transition">
                    Enroll Now
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Course Content */}
      <div className="max-w-7xl mx-auto px-4 py-12 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2">
            <section className="mb-12">
              <h2 className="text-2xl font-bold mb-6">What you'll learn</h2>
              <div className="bg-white rounded-lg p-6 shadow">
                <p className="text-gray-700">{course.whatYouWillLearn}</p>
              </div>
            </section>

            <section>
              <h2 className="text-2xl font-bold mb-6">Course Content</h2>
              <div className="space-y-4">
                {course.courseContent.map((section, index) => (
                  <div key={index} className="bg-white rounded-lg shadow">
                    <button
                      className="w-full px-6 py-4 flex items-center justify-between text-left"
                      onClick={() => toggleSection(index)}
                    >
                      <div className="flex items-center space-x-2">
                        <ChevronDown className={`w-5 h-5 transition-transform ${
                          openSections.includes(index) ? 'transform rotate-180' : ''
                        }`} />
                        <span className="font-medium">{section.sectionName}</span>
                      </div>
                      <span className="text-sm text-gray-500">
                        {section.subSection.length} lectures
                      </span>
                    </button>
                    {openSections.includes(index) && (
                      <div className="px-6 pb-4 space-y-2">
                        {section.subSection.map((lecture, lectureIndex) => (
                          <div
                            key={lectureIndex}
                            className="flex items-center space-x-3 text-gray-700 py-2"
                          >
                            <PlayCircle className="w-5 h-5 text-gray-400" />
                            <span>{lecture.title}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </section>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
